CREATE TABLE IF NOT EXISTS economic_decision_execution (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), decision_action_id uuid NOT NULL, profile_id uuid NOT NULL, execution_status text NOT NULL DEFAULT 'not_started', owner_id text NOT NULL, target_date timestamptz, completion_notes text, outcome_rating numeric(5,2), outcome_status text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS economic_decision_outcome_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), execution_id uuid NOT NULL, profile_id uuid NOT NULL, event_type text NOT NULL, from_status text, to_status text, actor_id text NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_decision_execution_profile ON economic_decision_execution(profile_id,updated_at DESC);